"use client"

import { useGetHomeData } from "../lib/ReactQuery/query/public/home/query"; 
import styles from "./HomePage.module.scss";
import Link from "next/link";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { zodResolver } from "@hookform/resolvers/zod";
import { useCreateAppointment } from "../lib/ReactQuery/query/public/appointments/query";

const quickFormSchema = z.object({
    name: z.string().min(2, "Введите имя"),
    phone: z.string().min(10, "Введите телефон")
});
type TQuickForm = z.infer<typeof quickFormSchema>;

export default function HomePage() {
    const { data, isLoading, isError } = useGetHomeData();
    const [isSuccess, setIsSuccess] = useState(false);
    const createAppointment = useCreateAppointment();

    const { register, handleSubmit, formState: { errors } } = useForm<TQuickForm>({
        resolver: zodResolver(quickFormSchema)
    });

    function onSubmitQuick(data: TQuickForm) {
        // В реальности тут надо передавать doctorId и serviceId, 
        // но для формы "перезвоните мне" мы просто отправим запрос без них
        // (тебе надо будет доработать API, чтобы он принимал пустые, либо создать отдельный API для лидов)
        setIsSuccess(true);
    }

    if (isLoading) return <div className={styles.loading}>Загрузка...</div>;
    if (isError) return <div className={styles.error}>Ошибка загрузки данных</div>;

    return (
        <main className={styles.page}>
            {/* 1. ГЛАВНЫЙ БАННЕР */}
            <section className={styles.hero}>
                <div className={styles.heroBgShape}></div>
                <div className={styles.heroContent}>
                    <span className={styles.badge}>Клиника нового поколения</span>
                    <h1 className={styles.heroTitle}>
                        Забота о вашем здоровье <br />
                        <span className={styles.heroAccent}>в Махачкале</span>
                    </h1>
                    <p className={styles.heroSubtitle}>
                        Современная клиника «Медис». Опытные врачи, новейшее оборудование и индивидуальный подход к каждому пациенту.
                    </p>
                    <div className={styles.heroActions}>
                        <Link href="/appointments" className={styles.btnPrimary}>
                            Записаться на прием
                        </Link>
                        <Link href="/services" className={styles.btnSecondary}>
                            Все услуги
                        </Link>
                    </div>
                </div>
                <div className={styles.heroImageWrap}>
                    <div className={styles.heroImage}>
                        Фото клиники / врача
                    </div>
                </div>
            </section>

            {/* 2. ПРЕИМУЩЕСТВА (4 в ряд) */}
            <section className={styles.featuresRow}>
                <div className={styles.featureBox}>
                    <div className={styles.iconCircle}>🕐</div>
                    <h3>Работаем 24/7</h3>
                    <p>Круглосуточный прием и экстренная помощь в любое время</p>
                </div>
                <div className={styles.featureBox}>
                    <div className={styles.iconCircle}>👨‍⚕️</div>
                    <h3>Опытные врачи</h3>
                    <p>Специалисты с многолетним стажем и учеными степенями</p>
                </div>
                <div className={styles.featureBox}>
                    <div className={styles.iconCircle}>🔬</div>
                    <h3>Точная диагностика</h3>
                    <p>Современное оборудование экспертного класса</p>
                </div>
                <div className={styles.featureBox}>
                    <div className={styles.iconCircle}>💙</div>
                    <h3>Забота и комфорт</h3>
                    <p>Индивидуальный подход и уютная атмосфера</p>
                </div>
            </section>

            {/* 3. УСЛУГИ */}
            <section className={styles.section}>
                <div className={styles.sectionHeader}>
                    <div>
                        <h2 className={styles.sectionTitle}>Наши услуги</h2>
                        <p className={styles.sectionSub}>Широкий спектр медицинской помощи для всей семьи</p>
                    </div>
                    <Link href="/services" className={styles.linkAll}>Все услуги →</Link>
                </div>
                <div className={styles.servicesGrid}>
                    {data.services.map((service: any) => (
                        <Link href={`/services/${service.slug}`} key={service.id} className={styles.serviceCard}>
                            <div className={styles.serviceHeader}>
                                <h3 className={styles.serviceTitle}>{service.title}</h3>
                                <span className={styles.serviceCategory}>{service.category?.title}</span>
                            </div>
                            <div className={styles.servicePrice}>
                                {service.price ? (service.priceFrom ? `от ${service.price} ₽` : `${service.price} ₽`) : "По запросу"}
                            </div>
                        </Link>
                    ))}
                </div>
            </section>

            {/* 4. БЛОК ОМС (ВАУ-ЭФФЕКТ) */}
            <section className={styles.omsBanner}>
                <div className={styles.omsContent}>
                    <h2>Лечение по ОМС</h2>
                    <p>Получите квалифицированную медицинскую помощь бесплатно по полису обязательного медицинского страхования. Мы работаем с ведущими страховыми компаниями.</p>
                    <Link href="/oms" className={styles.btnWhite}>Узнать подробнее</Link>
                </div>
                <div className={styles.omsImage}>🛡️</div>
            </section>

            {/* 5. ВРАЧИ */}
            <section className={styles.section}>
                <div className={styles.sectionHeader}>
                    <div>
                        <h2 className={styles.sectionTitle}>Наши врачи</h2>
                        <p className={styles.sectionSub}>Профессионалы, которым можно доверить здоровье</p>
                    </div>
                    <Link href="/doctors" className={styles.linkAll}>Все врачи →</Link>
                </div>
                <div className={styles.doctorsGrid}>
                    {data.doctors.map((doctor: any) => (
                        <Link href={`/doctors/${doctor.slug}`} key={doctor.id} className={styles.doctorCard}>
                            <div className={styles.doctorImage}>
                                {doctor.photoUrl ? (
                                    <img src={doctor.photoUrl} alt={doctor.name} />
                                ) : (
                                    <div className={styles.doctorPlaceholder}>
                                        {doctor.name.charAt(0)}
                                    </div>
                                )}
                            </div>
                            <div className={styles.doctorInfo}>
                                <h3 className={styles.doctorName}>{doctor.name}</h3>
                                <p className={styles.doctorSpec}>{doctor.specialization}</p>
                                <p className={styles.doctorExp}>Стаж: {doctor.experienceYears} лет</p>
                            </div>
                        </Link>
                    ))}
                </div>
            </section>

            {/* 6. БЛОГ */}
            {data.articles && data.articles.length > 0 && (
                <section className={styles.section}>
                    <div className={styles.sectionHeader}>
                        <div>
                            <h2 className={styles.sectionTitle}>Полезные статьи</h2>
                            <p className={styles.sectionSub}>Советы и рекомендации от наших специалистов</p>
                        </div>
                        <Link href="/blog" className={styles.linkAll}>Все статьи →</Link>
                    </div>
                    <div className={styles.articlesGrid}>
                        {data.articles.map((article: any) => (
                            <Link href={`/blog/${article.slug}`} key={article.id} className={styles.articleCard}>
                                <div className={styles.articleImage}>
                                    {article.coverUrl ? (
                                        <img src={article.coverUrl} alt={article.title} />
                                    ) : (
                                        <div className={styles.articlePlaceholder}></div>
                                    )}
                                </div>
                                <div className={styles.articleInfo}>
                                    <h3 className={styles.articleTitle}>{article.title}</h3>
                                    <p className={styles.articleDate}>{new Date(article.createdAt).toLocaleDateString("ru-RU")}</p>
                                </div>
                            </Link>
                        ))}
                    </div>
                </section>
            )}

            {/* 7. CTA БЛОК С ФОРМОЙ */}
            <section className={styles.ctaSection}>
                <div className={styles.ctaContent}>
                    <h2>Не откладывайте здоровье на потом</h2>
                    <p>Запишитесь на прием прямо сейчас. Наш администратор свяжется с вами для подтверждения времени и уточнения деталей.</p>
                    
                    <div className={styles.ctaPhone}>
                        <span>Или позвоните нам:</span>
                        <a href="tel:+79285558818">+7 (928) 555-88-18</a>
                    </div>
                </div>

                <div className={styles.ctaFormWrap}>
                    {isSuccess ? (
                        <div className={styles.ctaForm}>
                            <h3 style={{ color: '#166534' }}>✅ Заявка отправлена!</h3>
                            <p>Мы перезвоним вам в ближайшее время.</p>
                        </div>
                    ) : (
                        <form className={styles.ctaForm} onSubmit={handleSubmit(onSubmitQuick)}>
                            <h3>Записаться на прием</h3>
                            <p>Оставьте свои данные, и мы подберем удобное время</p>
                            
                            <input 
                                className={styles.input} 
                                type="text" 
                                placeholder="Ваше имя" 
                                {...register("name")} 
                            />
                            {errors.name && <span className={styles.err}>{errors.name.message}</span>}

                            <input 
                                className={styles.input} 
                                type="tel" 
                                placeholder="Номер телефона" 
                                {...register("phone")} 
                            />
                            {errors.phone && <span className={styles.err}>{errors.phone.message}</span>}

                            <button type="submit" className={styles.btnPrimary} style={{ width: '100%' }}>
                                Жду звонка
                            </button>
                            <p className={styles.agreement}>
                                Нажимая кнопку, вы соглашаетесь с политикой обработки персональных данных
                            </p>
                        </form>
                    )}
                </div>
            </section>
        </main>
    );
}